-- Committed dependency tokens are partitioned by domain and subject, never a
-- global sequence or directory row. Only compact projection writes invalidate.
CREATE TABLE crm.cache_versions(domain text NOT NULL,subject uuid NOT NULL,version uuid NOT NULL,PRIMARY KEY(domain,subject));
CREATE TABLE crm.cache_invalidations(transaction_id xid8 NOT NULL,domain text NOT NULL,subject uuid NOT NULL,PRIMARY KEY(transaction_id,domain,subject));
-- One deferred sentinel per transaction, independent of changed subject count.
CREATE TABLE crm.cache_flush_requests(transaction_id xid8 PRIMARY KEY);
CREATE FUNCTION crm.request_cache_flush() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 INSERT INTO crm.cache_flush_requests SELECT DISTINCT transaction_id FROM added ON CONFLICT DO NOTHING;
 RETURN NULL;
END $$;
CREATE TRIGGER cache_request_flush AFTER INSERT ON crm.cache_invalidations REFERENCING NEW TABLE AS added FOR EACH STATEMENT EXECUTE FUNCTION crm.request_cache_flush();
CREATE FUNCTION crm.flush_cache_invalidations() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 -- Consume all distinct subjects once, with deterministic conflict-lock order.
 WITH pending AS(DELETE FROM crm.cache_invalidations WHERE transaction_id=NEW.transaction_id RETURNING domain,subject)
 INSERT INTO crm.cache_versions(domain,subject,version)
 SELECT domain,subject,gen_random_uuid() FROM pending ORDER BY domain,subject
 ON CONFLICT(domain,subject) DO UPDATE SET version=excluded.version;
 DELETE FROM crm.cache_flush_requests WHERE transaction_id=NEW.transaction_id;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER cache_flush AFTER INSERT ON crm.cache_flush_requests DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION crm.flush_cache_invalidations();
CREATE FUNCTION crm.queue_cache_invalidations() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE source_sql text;
BEGIN
 source_sql=CASE TG_OP WHEN 'INSERT' THEN 'SELECT * FROM added' WHEN 'DELETE' THEN 'SELECT * FROM removed' ELSE 'SELECT * FROM added UNION ALL SELECT * FROM removed' END;
 EXECUTE 'WITH changed AS ('||source_sql||'), keys AS ('||TG_ARGV[0]||') INSERT INTO crm.cache_invalidations SELECT pg_current_xact_id(),domain,subject FROM keys WHERE subject IS NOT NULL GROUP BY domain,subject ORDER BY domain,subject ON CONFLICT DO NOTHING';
 RETURN NULL;
END $$;
CREATE TRIGGER cache_i AFTER INSERT ON crm.profiles REFERENCING NEW TABLE AS added FOR EACH STATEMENT EXECUTE FUNCTION crm.queue_cache_invalidations('SELECT ''profile'' domain,id subject FROM changed');
CREATE TRIGGER cache_u AFTER UPDATE ON crm.profiles REFERENCING OLD TABLE AS removed NEW TABLE AS added FOR EACH STATEMENT EXECUTE FUNCTION crm.queue_cache_invalidations('SELECT ''profile'' domain,id subject FROM changed');
CREATE TRIGGER cache_d AFTER DELETE ON crm.profiles REFERENCING OLD TABLE AS removed FOR EACH STATEMENT EXECUTE FUNCTION crm.queue_cache_invalidations('SELECT ''profile'' domain,id subject FROM changed');
