INSERT INTO crm.cache_versions SELECT domain,subject,gen_random_uuid() FROM (WITH changed AS(SELECT * FROM crm.profiles) SELECT 'profile' domain,id subject FROM changed) q WHERE subject IS NOT NULL GROUP BY domain,subject ON CONFLICT(domain,subject) DO NOTHING;
