INSERT INTO crm.cache_versions SELECT domain,subject,gen_random_uuid() FROM (WITH changed AS(SELECT * FROM crm.conversations) SELECT 'messages' domain,coalesce(profile_id,id) subject FROM changed UNION ALL SELECT 'conversation',id FROM changed) q WHERE subject IS NOT NULL GROUP BY domain,subject ON CONFLICT(domain,subject) DO NOTHING;
INSERT INTO crm.cache_versions SELECT domain,subject,gen_random_uuid() FROM (WITH changed AS(SELECT * FROM crm.conversation_days) SELECT 'calendar' domain,coalesce(c.profile_id,c.id) subject FROM changed d JOIN crm.conversations c ON c.id=d.conversation_id) q WHERE subject IS NOT NULL GROUP BY domain,subject ON CONFLICT(domain,subject) DO NOTHING;
INSERT INTO crm.cache_versions SELECT domain,subject,gen_random_uuid() FROM (WITH changed AS(SELECT * FROM crm.message_months) SELECT 'messages' domain,coalesce(c.profile_id,c.id) subject FROM changed d JOIN crm.conversations c ON c.id=d.conversation_id) q WHERE subject IS NOT NULL GROUP BY domain,subject ON CONFLICT(domain,subject) DO NOTHING;
INSERT INTO crm.cache_versions SELECT domain,subject,gen_random_uuid() FROM (WITH changed AS(SELECT * FROM crm.conversation_summaries) SELECT 'messages' domain,coalesce(c.profile_id,c.id) subject FROM changed d JOIN crm.conversations c ON(c.provider,c.account,c.external_id)=(d.provider,d.account,d.conversation)) q WHERE subject IS NOT NULL GROUP BY domain,subject ON CONFLICT(domain,subject) DO NOTHING;
INSERT INTO crm.cache_versions SELECT domain,subject,gen_random_uuid() FROM (WITH changed AS(SELECT * FROM crm.page_entity_counts) SELECT 'metrics' domain,subject FROM changed) q WHERE subject IS NOT NULL GROUP BY domain,subject ON CONFLICT(domain,subject) DO NOTHING;
INSERT INTO crm.cache_versions SELECT domain,subject,gen_random_uuid() FROM (WITH changed AS(SELECT * FROM crm.activities) SELECT 'activity' domain,id subject FROM changed) q WHERE subject IS NOT NULL GROUP BY domain,subject ON CONFLICT(domain,subject) DO NOTHING;
INSERT INTO crm.cache_versions SELECT domain,subject,gen_random_uuid() FROM (WITH changed AS(SELECT * FROM crm.media_links) SELECT 'media' domain,CASE WHEN c.entity_type='profile' THEN c.entity_id ELSE p.profile_id END subject FROM changed c LEFT JOIN crm.page_posts p ON p.id=c.entity_id) q WHERE subject IS NOT NULL GROUP BY domain,subject ON CONFLICT(domain,subject) DO NOTHING;
INSERT INTO crm.cache_versions SELECT domain,subject,gen_random_uuid() FROM (WITH changed AS(SELECT * FROM crm.media_assets) SELECT 'media-assets' domain,id subject FROM changed UNION ALL SELECT 'media',CASE WHEN l.entity_type='profile' THEN l.entity_id ELSE p.profile_id END FROM changed c JOIN crm.media_links l ON l.media_id=c.id LEFT JOIN crm.page_posts p ON p.id=l.entity_id) q WHERE subject IS NOT NULL GROUP BY domain,subject ON CONFLICT(domain,subject) DO NOTHING;

CREATE TRIGGER cache_i AFTER INSERT ON crm.source_chat_months REFERENCING NEW TABLE AS added FOR EACH STATEMENT EXECUTE FUNCTION crm.queue_cache_invalidations('SELECT ''messages'' domain,l.profile_id subject FROM changed c JOIN crm.source_account_links l ON l.account_id=c.account_id');
CREATE TRIGGER cache_u AFTER UPDATE ON crm.source_chat_months REFERENCING OLD TABLE AS removed NEW TABLE AS added FOR EACH STATEMENT EXECUTE FUNCTION crm.queue_cache_invalidations('SELECT ''messages'' domain,l.profile_id subject FROM changed c JOIN crm.source_account_links l ON l.account_id=c.account_id');
CREATE TRIGGER cache_d AFTER DELETE ON crm.source_chat_months REFERENCING OLD TABLE AS removed FOR EACH STATEMENT EXECUTE FUNCTION crm.queue_cache_invalidations('SELECT ''messages'' domain,l.profile_id subject FROM changed c JOIN crm.source_account_links l ON l.account_id=c.account_id');
CREATE TRIGGER cache_i AFTER INSERT ON crm.message_months_utc REFERENCING NEW TABLE AS added FOR EACH STATEMENT EXECUTE FUNCTION crm.queue_cache_invalidations('SELECT ''messages'' domain,coalesce(c.profile_id,c.id) subject FROM changed d JOIN crm.conversations c ON c.id=d.conversation_id');
CREATE TRIGGER cache_u AFTER UPDATE ON crm.message_months_utc REFERENCING OLD TABLE AS removed NEW TABLE AS added FOR EACH STATEMENT EXECUTE FUNCTION crm.queue_cache_invalidations('SELECT ''messages'' domain,coalesce(c.profile_id,c.id) subject FROM changed d JOIN crm.conversations c ON c.id=d.conversation_id');
CREATE TRIGGER cache_d AFTER DELETE ON crm.message_months_utc REFERENCING OLD TABLE AS removed FOR EACH STATEMENT EXECUTE FUNCTION crm.queue_cache_invalidations('SELECT ''messages'' domain,coalesce(c.profile_id,c.id) subject FROM changed d JOIN crm.conversations c ON c.id=d.conversation_id');
